import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"渙","description":"高島易斷 - 渙","frontmatter":{"title":"渙","description":"高島易斷 - 渙"},"headers":[],"relativePath":"classics/takashima/059.md","filePath":"classics/takashima/059.md"}'),i={name:"classics/takashima/059.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="渙" tabindex="-1">渙 <a class="header-anchor" href="#渙" aria-label="Permalink to “渙”">​</a></h1><h2 id="渙-1" tabindex="-1">渙 <a class="header-anchor" href="#渙-1" aria-label="Permalink to “渙”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>渙：亨。王假有廟，利涉大川，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《正義》曰：“散難釋險，故謂之渙”；難散則理平，險釋則心通，故亨。卦體三陰三陽，自《乾》《坤》來，《乾》為王，故曰“王”。旁通《豐》，《豐》《彖》辭曰“王假之”，故曰“假”。上互《艮》，《艮》為宗廟，故曰“有廟”。《坎》為大川，《巽》為利，下互《震》，《震》為足，有涉之象，故曰“利涉大川”。廟者，鬼神之所在也。《中庸》言“鬼神之德，洋洋乎如在其上，如在其左右”，渙之至盛者也。“大川”，眾流之所歸也，注焉而不滿，酌焉而不竭，渙之顯著者也，於假廟見揚詡之盛，於涉川得利濟之宏。然《渙》雖主散，形象則發揚於外，而精神貴凝聚於中，故曰“利貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>風行水上，渙，先王以享於帝，立廟。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>先王見風之虛，得鬼神之象，見《坎》之盈，得祭祀之象。夫風無形，遇水而成形，非水則風不可見；鬼神無睹，入廟而如睹，非廟則上帝祖考不可見。聚則為有，散則為無，鬼神之情狀，猶風之行水上也。人心誠敬之所聚，莫如鬼神，故大難始定，人心未寧之時，享帝而告成功，立廟而事祖考，聚將散之神靈，安鎮之以接天神，交祖考。蓋物本於天，人本於祖，故享帝以報其生成之恩，立廟以報其功德之盛，使天下之人，皆尊尊親親，不忘其本，以聚人心之渙散，故曰“先王以享於帝立廟”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運途亨通，有乘風破浪之概。</p><p>○　問戰徵：利用海軍。</p><p>○　問營商：財水流通，得天神護佑，大利。</p><p>○　問功名：風隨帆轉，水到渠成，有即日成名之象。</p><p>○　問家宅：宜禱告神祗，自然獲福。</p><p>○　問婚姻：中男長女，自成佳偶。</p><p>○　問疾病：“風行水上”，去而不留，病象危矣；立廟”，有魂歸窀穸之象，故兇。</p><p>○　問失物：難得。</p><p>○　問六甲：春夏生女，秋冬生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初處《坎》之下，《坎》為險，初乃始陷於險者也。陷《坎》者，利用拯，何以拯之？初與二近，二得乾氣，《乾》為馬，《乾》健故“馬壯”。初得二拯，如馬之因風而走，得以脫險也，故“吉”。按；《明夷》亦曰“用拯馬壯，吉”，《明夷》下互《坎》，二動為《乾》，故“用拯”亦取《乾》馬，與《渙》初同象。《傳》以“順”釋之，初本《坤》體，《坤》為順，以《坤》之順，用《乾》之健，是以吉也。《明夷》《傳》曰“順以則也”，其旨亦同。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運；運多險難，幸而遇救，危而反吉。</p><p>○　問戰徵：初次臨陣，賴戰馬精良，得以解圍出險，故吉。</p><p>○　問營商：資本微薄，深幸同事相助，得以獲利。</p><p>○　問功名：行午馬運，必可成名。</p><p>○　問家宅：新建大廈，好有祿馬臨向，吉。</p><p>○　問婚姻：《乾》造以肖馬者吉。</p><p>○　問疾病：病宜急治，得遇馬姓醫士為吉。</p><p>○　問行人：驛馬已動，即日可歸。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《渙》之《中孚》。</p><p>斷曰：初六當《坎》之始，“坎者，陷也”，如身陷坎險，一時難以自脫。初爻偶體屬陰，用以拯者必藉陽剛，馬《乾》象，得《乾》剛之氣，故足以拯之，是初以遇拯得吉也，即卜筮書所謂“絕處逢生”之象。今足下佔氣運，得初爻辭，知足下現時運途，正在困難之中，幸賴朋友，力為救護，得以脫離災厄。足下惟當順從其言，自可逢凶化吉。此友或系肖馬，或系姓馬，當必有暗合其象者。《易》佔之神妙，往往不可測度，足下後當自知之。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>九二以陽居陰，象取以陽假陰，故《彖》雲假廟，二當之。下互《震》，《震》為奔，上互《艮》，《艮》為堅木，有機之象；二與五應，機，謂五也。“渙奔其機”，謂假廟而奔就神幾，機幾字通，即《家語》“仰視榱桷，俯察機筵”是也。王在廟中，洞洞屬屬，以其恍惚，以與神明交，斯渙者假矣，故“悔亡”。《象傳》以“得其願”釋之，謂駿奔在廟，得受其福，故曰“得願也”。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：運途順適，得如所願，災悔俱亡。</p><p>○　問營商：運貨貿易，得所憑依，可以如願而償也，吉。</p><p>○　問功名：所願必遂。</p><p>○　問戰徵：雖當渙散敗奔，得所依藉，可圖恢復，何悔之有？</p><p>○　問婚姻：內卦《坤》體，二變為《乾》成《坎》，《坎》為中男；外卦《乾》體，四變為《坤》成《巽》，《巽》為長女，此配必女長於男。木水相生，佳偶也。</p><p>○　問家宅：此宅眷屬有奔敗之難，幸在外得所憑依，所謂適我願也。</p><p>○　問疾病：鬱鬱不樂，隱几而臥，得遇良醫，可以無憂。</p><p>○　問六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人梔尾某曰：餘曩以己地，出押於某華族，訂立券證，約以後日得金，准許備價取贖。至今地價騰貴，照曩時押價，一增其三，某華族因之背盟，指不許贖。餘遂使代言人及壯士逼索，某華族懼，乃挽餘親戚某，出為談判。餘不得已以若干金，酬報代言人與壯士，囑為了事，而壯士意猶不滿，遷怒於餘，意欲要路狙擊，餘甚患之。請佔其處置如何？筮得《渙》之《觀》。</p><p>斷曰：內卦為《坎》，《坎》者險也，難也；外卦為《巽》，《繫辭》曰“巽以行權”，謂《巽》得行其權變也。二爻曰“渙奔其機”，“奔”，奔避其難也，二與五應，謂奔就於五也。五處《巽》中，謂能“巽以行權”，足以渙散其難，故得“悔亡”。就此爻象，教足下奔避於外，自得有人出而處置，可以無悔。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三體坎水，上體《巽》風，三之趨上，如水過風而流，木得水而浮，有相待而渙散者也，故三至上互《艮》，《艮》為躬，曰“渙其躬，無悔”。《象傳》曰“志在外”，謂外卦也，志應夫上也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：三處《坎》之極，是運當坎險之時，忘身赴難，得以出險，可免悔也。</p><p>○　問戰徵：能國而忘身，忠勇可嘉，去復何悔？</p><p>○　問營商：運貨在外，跋涉風波，備嘗艱苦，有重財輕命之象。</p><p>○　問功名：有殺身成仁，名垂竹帛之榮。</p><p>○　問婚姻：有捐軀盡節之志，可悲，可嘉。</p><p>○　問家宅：此宅臨坎水之上，宅主宜出行在辦，得可免災。</p><p>○　問行人：未歸。</p><p>○　問六甲：分娩在即，生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人某來，請佔氣運，筮得《渙》之《巽》。</p><p>斷曰：《渙》之三爻，正當《坎》難之極，是身陷坎中而不能解脫也；惟賴上爻遠來援救，斯得渙然消散，可以無悔。今足下佔氣運，得《渙》三爻，知足下運途淹蹇，譬如行船入海，正遇風波之險，須得遠來巨舟，相為救援，斯能共脫險厄，得遠災悔，以保身命。三爻居內外卦之交，內《坎》外《巽》，《坎》，險也；《巽》，順也，有出險入順之象，是以“無悔”。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>六四居《巽》之始，卦體本《乾》，下畫化《坤》成《巽》，《坤》為眾，《坤》化《巽》，則其群渙矣。《坎》剛中得《乾》之元，故曰“渙其群，元吉”。上互《艮》，《艮》為丘，丘，聚也，高也，謂既渙其坎險，又復聚而成為高丘，是渙中有聚也，故曰“渙有丘”。四為《巽》卦之主，《繫辭》曰，“巽，德之制也”，又曰“巽稱而隱”，謂《巽》能因事制宜，隱見無常，化裁之妙，有非尋常所可測度者，故曰“匪夷所思”。《傳》以“光大”釋之，謂四出《坎》入《巽》，所以化險為夷者，正賴此正大光明之作用也。《坤》曰“含宏光大”，四得《坤》氣，四之“光大”，即自《坤》來也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：能解脫困難，覆成基業，正大運亨通之時。</p><p>○　問營商：絕大手段，能散財濟危，又能獨成丘壑。</p><p>○　問功名：有獨出冠時之概。</p><p>○　問戰徵：軍容之盛，忽散忽聚，忽高忽低，忽而萬馬無聲，忽而一丘高峙，變化之妙，有出意表者，此神化之兵也。</p><p>○　問疾病：散其外邪，又當聚其元氣，病自療矣。</p><p>○　問家宅：鄰居曠遠，獨成一家，自得幽趣，吉。</p><p>○　問訟事：“渙其群”，其訟必解矣，吉。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>長崎女商大浦阿啟，明治七八年間，管理橫濱制鐵所。一日將乘名古屋船歸鄉，預電報知家人，期以某日到家。屆期有報，名古屋船於周防遭難，家人驚愕，急以電信問餘。餘不知大浦氏果否乘船，亦不知此船有否遇險，無已，乃為一筮，筮得《渙》之《訟》。</p><p>斷曰：此卦《巽》為木，《坎》為水，舟浮海上之象。其辭曰：“渙其群，元吉。渙有丘，匪夷所思。”“渙其群”者，謂離眾人而出險也；“渙有丘”者，謂出險而獨在丘上也；“匪夷所思”者，謂不須憂慮也。由是觀之，知必脫其難也。餘即以此佔，電覆長崎，長崎家人得此報，疑信未決。未幾大浦有電到家，雲已脫險，家人始安。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五為尊位，《彖》所稱“王假”，五當之。號，令也，“大號”，大政令也。五有剛中之德，以天下之險為己險，欲渙散天下之險，以發此“大號”也。“渙汗”者，劉向雲：號令如汗，出而不返者。王者無私居，畿甸非近，要荒非遠，一人之身，渙之即為萬民，一人之心，渙之即為萬幾，佈於四海，猶汗出於身，而浹於四體，故曰“渙汗”。天下之困苦，得仁政而解，一身之邪熱，得汗出而消，其所渙一也。三至五體《艮》，《艮》為居，“王居”者，京師也。《論語》所云“譬如北辰，居其所，而眾星拱之”者，王居之謂也。“渙王居”者，號令之渙，自近而遠，其單敷萬方者，要必正位凝命，自王居始也。“無咎”，即“履帝位而不疚”之意，《象傳》以“正位”釋之，蓋以九五為正位，王者居之，得以號令天下。以一億兆之心，而濟萬民之險，皆由君德與君位正當之功也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：運位得正，語默動靜，百事皆吉。</p><p>○　問營商：地位正當，貨物流通，所到無不獲利。</p><p>○　問功名：位近至尊，名聞天下，大吉。</p><p>○　問戰徵：號令嚴明，軍威整肅，得奏汗馬之勳。</p><p>○　問婚姻：必得貴婿。</p><p>○　問家宅：此宅非尋常百姓之家。</p><p>○　問疾病：一汗即愈。</p><p>○　問六甲：生女，主貴。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十七年六月，朝鮮有東學黨之亂，有朝鮮人樸泳孝者，流寓我邦，眷念故國，實抱杞憂。請餘一佔，筮得《渙》之《蒙》。</p><p>斷曰：“渙者，散也”，全卦大意，皆以散難釋險為主。五爻居尊為王，“大號”者，王所散佈之政令也；“渙汗”者，謂其令出必行，猶汗出於身而不返也。足見號令嚴明，可以解脫險難，奠厥攸居，斯無咎矣。今樸氏佔問伊國治亂，得《渙》五爻，玩其爻辭，知伊國禍逼王居。九五者，王也，王當速發號令，詔告天下，渙散兇黨，奠定王居，斯可保全而無咎也。卦體下互《震》，《震》屬東方，則救護朝鮮者，必在我國也。樸氏可無憂焉。</p><p>明治二十七年六月，山田德明氏，偕美人某來問曰：今回日本兵渡航朝鮮，抑與朝鮮開戰乎？餘曰；軍事機密，非餘所知，惟一佔，則可以知之。筮得《渙》之《蒙》。</p><p>斷曰：汗者膚腠之所出，出則宣人之臃滿，愈人之疾苦，猶王者之有教令，釋天下之難，使之各得其所也，故曰“渙汗其大號”。“渙王居”者，謂大號之宣佈，始於王居，蓋有自近及遠，自內及外之旨焉。卦名曰《渙》，其義總在渙散險難也。今佔我國與朝鮮機密軍事，得《渙》五爻，乃知我國此番得聞朝鮮亂耗，速發號令，派遣軍艦，遠航韓國，旁觀者以為我國將與朝鮮啟釁，玩此爻辭，可信別無他意。美人得此斷辭，遂譯作西文，揭布外國新聞。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上與三應，三體《坎》，為血卦，故曰“渙其血”。蓋人身血脈以流通為安；以鬱結致病，“渙其血”，斯體氣舒暢，則憂患自消。“逖”，憂也，《坎》為逖，且上爻居《渙》之極，已出坎險，故曰“去逖出”。逖既去矣，咎自無也。《象傳》以“遠害”釋之，謂上去《坎》已遠，故害亦遠矣。一說，謂上出卦外，逖，遠也，身之有血，猶川之有水，喻言川流通達，風馳遠去也。即取《大象》“風行水上”之意。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：運途通達，災去福來。</p><p>○　問戰徵：卦體從《乾》《坤》來，《坤》上曰“龍戰於野，其血玄黃”，有戰則兩傷之象。</p><p>○　問營商：血者，資財也。商舶遠出，貿易亨通，可以獲利，自無憂也。</p><p>○　問功名：有投筆從軍之象。</p><p>○　問婚姻：有遠嫁之象。</p><p>○　問家宅：宅主防有血光之災，遠避可以無咎。</p><p>○　問疾病：是氣血淤結之患，宜疏通脈絡，可以免災。</p><p>○　問失物：此物已去遠，不可復得。</p><p>○　問訟事：宜遠出避之，無咎。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>友人某來，請佔氣運，筮得《渙》之《坎》。</p><p>斷曰：《渙》者脫難之卦，上處《渙》終，為困難消散之時也。今足下佔氣運，得《渙》上爻，知足下目下險難已解，譬如病者，血脈融通，憂患悉去，可以無咎矣。上爻《渙》象己終，此後出《渙》入《節》，節財節慾，足下皆當留意焉。</p><p>三十一年，佔英國與俄國交際，筮得《渙》之《坎》。</p><p>斷曰：《渙》卦三陰三陽，本從《乾》《坤》《否》來，上居《巽》極，即《乾》之上，陽亢則戰，有“其血玄黃”之象，故曰“渙其血”。《小畜》所謂“血去惕出”，亦謂《乾》也。“逖”或作“惕”。《小畜》以陰陽感孚而“血去”，《渙》以風水相濟而血《渙》，是《渙》卦本有險難，幸得渙散而無咎也。今佔英俄兩國交際，得《渙》上爻，俄在陸地，英屬海疆，當以《巽》為俄，《坎》為英。陸地專以鐵道稱強，海疆專以輪船示武。陸戰者得勝，而後勝者又畏報復，敗者更防再襲，扼要據險，不懈兵備，是俄國之所急急也。在英託名商船保護，派艦遠出，竊窺海防，得乘其隙，即強生葛藤，逼使割地講和，此英國之狡計也。是以陸地諸國，多困於軍資，惟英國軍資，年增年饒，獨握富有之權，以爭雄於海上，而俄則以陸軍之強，陸地之險，蠶食鄰邦，故近來宇內諸國，皆視英俄為虎狼之國也。俄嘗於西伯利亞鐵道未通，故生事端，為英所鎮；地中海要處，為糧食彈藥告乏，不能驟動大兵；英又以阿富汗、波斯等國既通於俄，恐印度有內亂；且自知久矣壟斷富利，受各國之嫌惡。今孛法與俄訂為同盟，恐聯約合謀，當必起一大役也，故欲教唆支那，以防俄國之跋扈。然英以有海軍而乏陸軍，亦不能如意，且一朝取敗，則濠洲、加奈陀亞、弗利加等要地，恐亦不能保全，故擴張海軍，以當各國。蓋俄恃鐵道之全通，英恃海軍之擴張，恰似兩雄相對，爻曰“渙其血”，謂兩國宜通其聲氣，乃可無事，即各國亦可遠害矣。此近時之形勢也，故《傳》曰“渙其血，遠害也”。</p>',111)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
